// Checkout conversion module: tracks paid events and updates revenue metrics
const fs = require('fs');
const path = require('path');

const REVENUE_FILE = path.join(__dirname, '..', 'data', 'revenue.json');

function ensureRevenueFile() {
  if (!fs.existsSync(path.dirname(REVENUE_FILE))) {
    fs.mkdirSync(path.dirname(REVENUE_FILE), { recursive: true });
  }
  if (!fs.existsSync(REVENUE_FILE)) {
    fs.writeFileSync(REVENUE_FILE, JSON.stringify({ paidEvents: 0, conversionRate: 0, leads: 0 }));
  }
}

function recordPaidEvent() {
  ensureRevenueFile();
  const data = JSON.parse(fs.readFileSync(REVENUE_FILE, 'utf8'));
  data.paidEvents = (data.paidEvents || 0) + 1;
  if (data.leads > 0) {
    data.conversionRate = data.paidEvents / data.leads;
  }
  fs.writeFileSync(REVENUE_FILE, JSON.stringify(data, null, 2));
  return data;
}

function getRevenueMetrics() {
  ensureRevenueFile();
  return JSON.parse(fs.readFileSync(REVENUE_FILE, 'utf8'));
}

module.exports = { recordPaidEvent, getRevenueMetrics };
